import * as Notifications from 'expo-notifications';
import Constants from 'expo-constants';

const navigationRef = createNavigationContainerRef<any>();

// 🔹 Configuração global para notificações (evita conflitos)
Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: true,
  }),
});

function useRegisterForPushNotifications(usuario: User | null) {
  useEffect(() => {
    async function register() {
      if (!usuario) return;

      if (Platform.OS === 'web') {
        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission !== 'granted') {
          return;
        }
        await registerFirebaseWebPush(usuario);
        return;
      }
      if (Constants.isDevice) {
        const { status: existingStatus } = await Notifications.getPermissionsAsync();
        let finalStatus = existingStatus;
        if (existingStatus === 'undetermined') {
          const { status } = await Notifications.requestPermissionsAsync();
          finalStatus = status;
        }
        if (finalStatus !== 'granted') { 
          return; 
        }
        const token = (await Notifications.getExpoPushTokenAsync()).data;
        await setDoc(doc(firestore, 'usuarios', usuario.uid), { expoPushToken: token }, { merge: true });
        console.log('Token salvo:', token);
      }
    }
    register();
  }, [usuario]);
}

function useWebNotificationGate(usuario: User | null) {
  const [permission, setPermission] = useState<NotificationPermission | 'unsupported' | 'checking'>('checking');
  const [registering, setRegistering] = useState(false);

  useEffect(() => {
    if (Platform.OS !== 'web' || !usuario || typeof window === 'undefined') {
      setPermission('checking');
      return;
    }

    if (!('Notification' in window) || !('serviceWorker' in navigator)) {
      setPermission('unsupported');
      return;
    }

    setPermission(Notification.permission);
    const handleFocus = () => setPermission(Notification.permission);
    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [usuario]);

  const requestPermission = async () => {
    if (!usuario || Platform.OS !== 'web' || !('Notification' in window)) return;

    setRegistering(true);
    try {
      await registerFirebaseWebPush(usuario);
      setPermission(Notification.permission);
    } finally {
      setRegistering(false);
    }
  };

  return {
    shouldBlock: Platform.OS === 'web' && !!usuario && permission === 'default',
    permission,
    registering,
    requestPermission,
  };
}

function useInstalledAppBadge(usuario: User | null) {
  useEffect(() => {
    if (Platform.OS !== 'web' || !usuario) {
      setInstalledAppBadge(0);
      return;
    }

    let escalaCount = 0;
    let repertorioCount = 0;
    let avisoCount = 0;

    const updateBadge = () => {
      setInstalledAppBadge(escalaCount + repertorioCount + avisoCount);
    };

    const unsubscribeEscalas = onSnapshot(doc(firestore, 'meta', 'escalas'), (snapshot) => {
      escalaCount = Number(snapshot.data()?.newCount || 0);
      updateBadge();
    });

    const unsubscribeRepertorios = onSnapshot(doc(firestore, 'meta', 'repertorios'), (snapshot) => {
      repertorioCount = Number(snapshot.data()?.newCount || 0);
      updateBadge();
    });

    const unsubscribeAvisos = onSnapshot(query(collection(firestore, 'avisos')), (snapshot) => {
      avisoCount = snapshot.docs.filter((docSnap) => {
        const visualizadosPor = docSnap.data().visualizadosPor;
        return !Array.isArray(visualizadosPor) || !visualizadosPor.includes(usuario.uid);
      }).length;
      updateBadge();
    });

    return () => {
      unsubscribeEscalas();
      unsubscribeRepertorios();
      unsubscribeAvisos();
    };
  }, [usuario]);
}

function obterVersaoMeta(data: any): number {
  const lastUpdated = data?.lastUpdated || data?.updatedAt || data?.criadoEm;
  if (typeof lastUpdated?.toMillis === 'function') return lastUpdated.toMillis();
  if (lastUpdated instanceof Date) return lastUpdated.getTime();
  if (typeof lastUpdated === 'number') return lastUpdated;

  const parsed = Date.parse(String(lastUpdated || ''));
  if (!Number.isNaN(parsed)) return parsed;

  return Number(data?.newCount || 0);
}

function useMetaUpdateNotifications(usuario: User | null) {
  const versoesIniciais = useRef<Record<string, number | null>>({
    escalas: null,
    repertorios: null,
  });

  useEffect(() => {
    if (!usuario) {
      versoesIniciais.current = { escalas: null, repertorios: null };
      return;
    }

    const observarMeta = (
      tipo: 'escalas' | 'repertorios',
      titulo: string,
      corpo: (count: number) => string
    ) => onSnapshot(doc(firestore, 'meta', tipo), async (snapshot) => {
      const data = snapshot.data();
      const count = Number(data?.newCount || 0);
      const versaoAtual = obterVersaoMeta(data);
      const versaoAnterior = versoesIniciais.current[tipo];

      if (versaoAnterior === null) {
        versoesIniciais.current[tipo] = versaoAtual;
        return;
      }

      versoesIniciais.current[tipo] = versaoAtual;

      if (count <= 0 || versaoAtual <= versaoAnterior) return;

      try {
        await Notifications.setBadgeCountAsync(count);
        await Notifications.scheduleNotificationAsync({
          content: { title: titulo, body: corpo(count), badge: count },
          trigger: null,
        });
      } catch (error) {
        console.log(`Erro ao notificar ${tipo}:`, error);
      }
    });

    const unsubscribeEscalas = observarMeta(
      'escalas',
      'Escala atualizada',
      (count) => count > 1 ? `${count} atualizacoes de escala` : 'Uma escala foi criada ou atualizada'
    );
    const unsubscribeRepertorios = observarMeta(
      'repertorios',
      'Repertorio atualizado',
      (count) => count > 1 ? `${count} atualizacoes de repertorio` : 'Um repertorio foi criado ou atualizado'
    );

    return () => {
      unsubscribeEscalas();
      unsubscribeRepertorios();
    };
  }, [usuario]);
}

function NotificationRequiredScreen({
  permission,
  registering,
  onRequestPermission,
}: {
  permission: NotificationPermission | 'unsupported' | 'checking';
  registering: boolean;
  onRequestPermission: () => void;
}) {
  const isDenied = permission === 'denied';
  const isUnsupported = permission === 'unsupported';

  return (
    <SafeAreaView style={styles.notificationGate}>
      <View style={styles.notificationPanel}>
        <View style={styles.notificationIcon}>
          <Text style={styles.notificationIconText}>!</Text>
        </View>
        <Text style={styles.notificationTitle}>Ative as notificacoes</Text>
        <Text style={styles.notificationText}>
          As notificacoes sao obrigatorias para receber novas escalas, repertorios e avisos importantes do ministerio.
        </Text>

        {isUnsupported ? (
          <Text style={styles.notificationWarning}>
            Este navegador nao suporta notificacoes PWA. Abra no Chrome, Edge ou instale o PWA pela tela inicial do celular.
          </Text>
        ) : isDenied ? (
          <Text style={styles.notificationWarning}>
            A permissao foi bloqueada. Libere as notificacoes nas configuracoes do navegador para continuar.
          </Text>
        ) : null}

        <Pressable
          style={[styles.notificationButton, (registering || isUnsupported) && styles.notificationButtonDisabled]}
          onPress={onRequestPermission}
          disabled={registering || isUnsupported}
        >
          <Text style={styles.notificationButtonText}>
            {registering ? 'Ativando...' : isDenied ? 'Tentar novamente' : 'Ativar notificacoes'}
          </Text>
        </Pressable>
      </View>
    </SafeAreaView>
  );
}

const InstallPWAButton = () => {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showButton, setShowButton] = useState(false);

  useEffect(() => {
    if (Platform.OS !== 'web') return;
    const handler = (e: any) => { 
      e.preventDefault(); 
      setDeferredPrompt(e); 
      setShowButton(true); 
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    await deferredPrompt.userChoice;
    setDeferredPrompt(null);
    setShowButton(false);
  };

  if (!showButton) return null;
  return (
    <View style={styles.pwaContainer}>
      <button onClick={handleInstallClick} style={styles.pwaBotao}>Instalar App</button>
    </View>
  );
};

const linking = {
  prefixes: [Platform.OS === 'web' ? window.location.origin + '/' : ''],
  config: {
    screens: {
      Inicio: '', CriarEscala: 'criar-escala', Escalas: 'escalas', DetalhesEscala: 'detalhes-escala',
      Repertorios: 'repertorios', AdicionarRepertorio: 'adicionar-repertorio', DetalheRepertorio: 'detalhe-repertorio',
      VisualizarArquivo: 'visualizar-arquivo', Presenca: 'presenca', Avisos: 'avisos',
      Ensaios: 'ensaios', Aniversariantes: 'aniversariantes', Agenda: 'agenda',
    },
  },
};

const notificationRouteByPath: Record<string, string> = {
  escalas: 'Escalas',
  repertorios: 'Repertorios',
  avisos: 'Avisos',
  ensaios: 'Ensaios',
  aniversariantes: 'Aniversariantes',
  agenda: 'Agenda',
};

function getNotificationRoute(url: string) {
  try {
    const parsed = new URL(url, typeof window !== 'undefined' ? window.location.origin : 'https://worldinovabr.github.io');
    const parts = parsed.pathname.split('/').filter(Boolean);
    const lastPart = parts[parts.length - 1] || '';
    return notificationRouteByPath[lastPart] || null;
  } catch {
    const normalized = url.split('?')[0].split('#')[0].split('/').filter(Boolean).pop() || '';
    return notificationRouteByPath[normalized] || null;
  }
}

function navigateFromNotificationUrl(url: string) {
  const route = getNotificationRoute(url);
  if (!route) return;

  if (navigationRef.isReady()) {
    navigationRef.navigate(route);
    return;
  }

  setTimeout(() => navigateFromNotificationUrl(url), 400);
}

export default function App(): JSX.Element {
  const [usuario, setUsuario] = useState<User | null>(null);
  const [carregando, setCarregando] = useState(true);
  const notificationGate = useWebNotificationGate(usuario);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (usuarioAtual) => {
      setUsuario(usuarioAtual && usuarioAtual.emailVerified ? usuarioAtual : null);
      setCarregando(false);
    });
    return unsubscribe;
  }, []);

  useRegisterForPushNotifications(usuario);
  useInstalledAppBadge(usuario);
  useMetaUpdateNotifications(usuario);

  useEffect(() => {
    if (Platform.OS !== 'web' || typeof navigator === 'undefined' || !usuario) return;

    const handleServiceWorkerMessage = (event: MessageEvent) => {
      if (event.data?.type !== 'WORSHIP_NOTIFICATION_CLICK' || !event.data?.url) return;
      navigateFromNotificationUrl(event.data.url);
    };

    navigator.serviceWorker?.addEventListener('message', handleServiceWorkerMessage);
    return () => navigator.serviceWorker?.removeEventListener('message', handleServiceWorkerMessage);
  }, [usuario]);

  if (carregando) {
    return (
      <SafeAreaView style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#FF9A3C" />
      </SafeAreaView>
    );
  }

  if (notificationGate.shouldBlock) {
    return (
      <NotificationRequiredScreen
        permission={notificationGate.permission}
        registering={notificationGate.registering}
        onRequestPermission={notificationGate.requestPermission}
      />
    );
  }

  return (
    <SafeAreaView style={styles.container} edges={['top', 'bottom']}>
      <NavigationContainer ref={navigationRef} linking={linking}>
        {usuario ? <AppNavigator /> : <AuthNavigator />}
        <InstallPWAButton />
        <Toast />
      </NavigationContainer>
    </SafeAreaView>
  );
}

